mapper.select:
SELECT EXISTS (
    SELECT 1
      FROM entry_qrs
     WHERE reservation_id = #{reservationId}
)

mapper.insert:
INSERT INTO entry_qrs (
       reservation_id
     , token_hash
     , qr_status
     , available_from
     , expires_at
     , issued_at
     , revoked_at
     , revoke_reason
     , created_at
     , updated_at
) VALUES (
       #{reservationId}
     , #{tokenHash}
     , NULL
     , #{availableFrom}
     , #{expiresAt}
     , #{now}
     , NULL
     , NULL
     , #{now}
     , #{now}
)
